      "path": "reconcile/matcher.py",
      "content": "from __future__ import annotations

from collections import Counter
from typing import Iterable

from .models import Discrepancy, Row


def find_discrepancies(left_rows: Iterable[Row], right_rows: Iterable[Row]) -> list[Discrepancy]:
    left_list = list(left_rows)
    right_list = list(right_rows)

    discrepancies: list[Discrepancy] = []

    # Build counters for left and right
    left_counter = Counter((r.merchant_order_id, r.provider_txn_id) for r in left_list)
    right_counter = Counter((r.merchant_order_id, r.provider_txn_id) for r in right_list)

    # Build lookup for right rows by key
    right_lookup: dict[tuple[str, str], Row] = {}
    for r in right_list:
        key = (r.merchant_order_id, r.provider_txn_id)
        if key not in right_lookup:
            right_lookup[key] = r

    # Build lookup for left rows by key (first occurrence)
    left_lookup: dict[tuple[str, str], Row] = {}
    for r in left_list:
        key = (r.merchant_order_id, r.provider_txn_id)
        if key not in left_lookup:
            left_lookup[key] = r

    # Detect duplicates on left
    for key, count in left_counter.items():
        if count > 1:
            row = left_lookup[key]
            discrepancies.append(
                Discrepancy(
                    kind="duplicate_left",
                    merchant_order_id=row.merchant_order_id,
                    provider_txn_id=row.provider_txn_id,
                    detail=f"Found {count} occurrences on left",
                )
            )

    # Detect missing_right and amount_mismatch
    for key, count in left_counter.items():
        if key not in right_counter:
            row = left_lookup[key]
            discrepancies.append(
                Discrepancy(
                    kind="missing_right",
                    merchant_order_id=row.merchant_order_id,
                    provider_txn_id=row.provider_txn_id,
                    detail="Found on left but not on right",
                )
            )
        elif count == 1:
            left_row = left_lookup[key]
            right_row = right_lookup[key]
            if left_row.amount_cents != right_row.amount_cents:
                discrepancies.append(
                    Discrepancy(
                        kind="amount_mismatch",
                        merchant_order_id=left_row.merchant_order_id,
                        provider_txn_id=left_row.provider_txn_id,
                        detail=f"Left: {left_row.amount_cents}, Right: {right_row.amount_cents}",
                    )
                )

    # Detect missing_left
    for key, count in right_counter.items():
        if key not in left_counter:
            row = right_lookup[key]
            discrepancies.append(
                Discrepancy(
                    kind="missing_left",
                    merchant_order_id=row.merchant_order_id,
                    provider_txn_id=row.provider_txn_id,
                    detail="Found on right but not on left",
                )
            )

    return discrepancies
